beforeExample:
public class Example {
    boolean isEnabled = true;
    public void method() {
        boolean result = !!isEnabled;
    }
}

afterExample:
public class Example {
    boolean isEnabled = true;
    public void method() {
        boolean result = isEnabled;
    }
}

negativeExample:
public class Example {
    boolean isEnabled = true;
    public void method() {
        boolean result = !isEnabled; // Single negation, should not change
        int a = 5;
        int b = ~a; // Bitwise NOT, should not change
    }
}
